IDS = [row[0] for row in CALLS]


def envelope_for(operation):
    return ENVELOPES[operation.replace(".", "_")]


def install(mock, method, path, operation):
    body = envelope_for(operation)
    return mock.request(method, f"{BASE}{path}").mock(return_value=httpx.Response(200, json=body))


@pytest.mark.parametrize("operation,method,path,query,body,cardinality,call", CALLS, ids=IDS)
def test_request_mapping(operation, method, path, query, body, cardinality, call):
    """Every method must put the request where the spec says it goes."""
    with respx.mock(base_url=BASE, assert_all_called=False) as mock:
        route = install(mock, method, path, operation)
        with zelf.ZelfAPIClient("sk_zelf_" + "0" * 64, max_retries=0) as client:
            result = call(client)

    assert route.called, operation
    request = route.calls.last.request
    assert request.method == method
    assert request.url.path == path
    for key, values in query.items():
        sent_values = request.url.params.get_list(key)
        assert sent_values == values, f"{operation} sent ?{key}={sent_values!r}, want {values!r}"
    if body:
        sent = json.loads(request.content)
        for key in body:
            assert key in sent, f"{operation} dropped body field {key}"
    if cardinality == "page":
        assert isinstance(result, zelf.Page)
    elif cardinality == "list":
        assert isinstance(result, list)


@pytest.mark.parametrize("operation,method,path,query,body,cardinality,call", CALLS, ids=IDS)
@pytest.mark.asyncio
async def test_request_mapping_async(operation, method, path, query, body, cardinality, call):
    """The async client must map a request exactly as the sync one does."""
    with respx.mock(base_url=BASE, assert_all_called=False) as mock:
        route = install(mock, method, path, operation)
        async with zelf.ZelfAPIClientAsync("sk_zelf_" + "0" * 64, max_retries=0) as client:
            await call(client)

    assert route.called, operation
    assert route.calls.last.request.url.path == path


PAGED = [row for row in CALLS if row[5] == "page"]


@pytest.mark.parametrize(
    "operation,method,path,query,body,cardinality,call",
    PAGED,
    ids=[row[0] for row in PAGED],
)
def test_auto_paging_walks(operation, method, path, query, body, cardinality, call):
    """Walking a page must issue the follow-up request its closure builds."""
    first = dict(envelope_for(operation))
    first["next"] = 2
    second = dict(envelope_for(operation))
    second["page"] = 2
    second["next"] = None

    with respx.mock(base_url=BASE, assert_all_called=False) as mock:
        route = mock.request(method, f"{BASE}{path}").mock(
            side_effect=[
                httpx.Response(200, json=first),
                httpx.Response(200, json=second),
            ]
        )
        with zelf.ZelfAPIClient("sk_zelf_" + "0" * 64, max_retries=0) as client:
            rows = list(call(client).auto_paging(max_pages=2))

    assert route.call_count == 2, operation
    assert rows


@pytest.mark.parametrize(
    "operation,method,path,query,body,cardinality,call",
    PAGED,
    ids=[row[0] for row in PAGED],
)
@pytest.mark.asyncio
async def test_auto_paging_walks_async(operation, method, path, query, body, cardinality, call):
    """The async page closure is a separate code path from the sync one."""
    first = dict(envelope_for(operation))
    first["next"] = 2
    second = dict(envelope_for(operation))
    second["page"] = 2
    second["next"] = None

    with respx.mock(base_url=BASE, assert_all_called=False) as mock:
        route = mock.request(method, f"{BASE}{path}").mock(
            side_effect=[
                httpx.Response(200, json=first),
                httpx.Response(200, json=second),
            ]
        )
        async with zelf.ZelfAPIClientAsync("sk_zelf_" + "0" * 64, max_retries=0) as client:
            page = await call(client)
            rows = [row async for row in page.auto_paging(max_pages=2)]

    assert route.call_count == 2, operation
    assert rows


def test_api_key_header_is_sent_once():
    """A caller's own key header must not replace or duplicate the client's."""
    operation, method, path, _query, _body, _cardinality, call = CALLS[0]
    with respx.mock(base_url=BASE, assert_all_called=False) as mock:
        route = install(mock, method, path, operation)
        with zelf.ZelfAPIClient(
            "sk_zelf_" + "0" * 64,
            max_retries=0,
            default_headers={"X-API-Key": "sk_zelf_" + "9" * 64},
        ) as client:
            call(client)

    sent = route.calls.last.request.headers.get_list("x-api-key")
    assert sent == ["sk_zelf_" + "0" * 64]


@pytest.mark.parametrize("name", sorted(MODELS), ids=sorted(MODELS))
def test_model_round_trip(name):
    """Every generated model must decode its sample and re-encode it unchanged."""
    model = getattr(zelf, name, None)
    if model is None:
        pytest.skip(f"{name} is not exported")
    sample = MODELS[name]
    parsed = model.model_validate(sample)
    for field in type(parsed).model_fields:
        getattr(parsed, field)
    assert repr(parsed)
    again = model.model_validate(parsed.model_dump(by_alias=True))
    assert again == parsed
